  'food.name': 'SGS Analytics (ehemals Synlab)',
  'food.description':
    'Dieses Plugin stellt die Verbindung zum Futterlabor des SGS Analytics her.',
  'food.input_description':
    'Mit den folgenden drei Schritten aktivieren Sie Ihre Laborschnittstelle:<ol><li>Bitte aktivieren Sie mit dem Klick auf den „Aktivieren“-Button  unten dieses Plugin, um Ihre Futteranalysen von diesem Labor direkt zu fodjan übertragen zu bekommen.</li><li>Bitte tragen Sie in das Feld „Kundennummer“ Ihre Debitoren-/Kundennummer Ihres Labors ein. Diese finden Sie zum Beispiel auf Ihren früheren Analysen oder Rechnungen.</li><li>Nutzen Sie den Probenbegleitschein aus fodjan, dann bekommen wir automatisch eine Kopie aller Ihrer Analysen direkt vom Labor, um Sie Ihnen in fodjan unter „Futteranalysen“ zur Verfügung zu stellen.</li></ol><br><strong>Den Probenbegleitschein finden Sie oben rechts in der Ansicht „Futteranalysen“</strong>.',
  'food.setup_description':
    'Um Ihre SGS-Analysen auch in fodjan importiert zu bekommen, folgen Sie diesen 3 Schritten.',
  'lkvbb.name': 'LKV BB Futterlabor',
  'lkvbb.description':
    'Dieses Plugin stellt die Verbindung zum Futterlabor des LKV Berlin-Brandenburg her.',
  'lkvbb.input_description':
    'Mit den folgenden drei Schritten aktivieren Sie Ihre Laborschnittstelle:<ol><li>Bitte aktivieren Sie mit dem Klick auf den „Aktivieren“-Button  unten dieses Plugin, um Ihre Futteranalysen von diesem Labor direkt zu fodjan übertragen zu bekommen.</li><li>Nutzen Sie den Probenbegleitschein aus fodjan, dann bekommen wir automatisch eine Kopie aller Ihrer Analysen direkt vom Labor, um Sie Ihnen in fodjan unter „Futteranalysen“ zur Verfügung zu stellen. Für das Futterlabor des LKV Berlin/Brandenburg benötigen Sie keine eigene Kundennummer. Nachdem Sie den ersten Untersuchungsauftrag über fodjan abgeschickt haben, erfolgt die Zuordnung über die fodjan-eigene Kunden-Nummer.</li></ol><br><strong>Den Probenbegleitschein finden Sie oben rechts in der Ansicht „Futteranalysen“</strong>.',
  'lkvbb.setup_description':
    'Um Ihre LKV BB-Analysen auch in fodjan importiert zu bekommen, folgen Sie diesen 2 Schritten.',
