  'cow_connect.name': 'CowConnect',
  'cow_connect.description':
    "Die CowConnect Box ist eine Hardwarelösung, welche bei Futtermischwägen nachgerüstet werden kann. Sie sammelt Daten zur Futteraufnahme, Futtereffizienz und den Futterkosten. Über eine App sind, die Daten jederzeit über die Cloud abrufbar.<br><br><strong>Funktionsweise:</strong><ol><li>Die fodjan-Schnittstelle überträgt Ihre Rationen direkt in die Cloud von CowConnect. CowConnect bringt die Werte, dann auf die die mobile Box am Futtermischwagen.</li><li>Die übertragene Ration/das Rezept wird auf der Hardware von CowCconnect angezeigt. Die Mischung des Futters und die Fütterung kann beginnen.</li><li>Die tatsächlich gefütterten Rationen werden an die CowConnect Cloud gesendet und kommen über die CowConnect Schnittstelle zu fodjan ins System.</li></ol><br><strong>Berechnung:</strong><br>Keine Berechnungen notwendig<br><br><strong>Besonderheiten:</strong><br>Da fodjan noch kein „Pen-“ bzw. „Locationmanagement hat, um eine Tiergruppe, die an verschiedenen Standorten gefüttert wird, zu verwalten, werden Rezepte/Rationen immer nur für eine Tiergruppe übergeben. Die Zuordnung zu den Pens erfolgt durch CowConnect.<br><br>'",
  'cow_connect.input_description':
    "Um sich mit CowConnect zu verbinden müssen Sie zunächst die Verbindung zwischen fodjan und CowConnect herstellen. Dazu loggen Sie sich in das CowConnect-Portal ein und gehen zum Bereich der Schnittstellen. Die hier angezeigte FARM UID fügen sie bei Fodjan ein und aktivieren damit die Schnittstelle.'",
  'mmm_feednow.name': "MmmooOgle FeedNow!'",
  'mmm_feednow.description':
    "Die MmmooOgle FeedNow! Box ist eine Hardwarelösung, welche bei Futtermischwägen nachgerüstet werden kann. Sie sammelt Daten zur Futteraufnahme, Futtereffizienz und den Futterkosten. Über eine App sind, die Daten jederzeit über die Cloud abrufbar.<br><br>'",
  'mmm_feednow.input_description':
    "Um sich mit MmmooOgle FeedNow! zu verbinden müssen Sie zunächst die Verbindung zwischen fodjan und MmmooOgle FeedNow! herstellen.'",
  'dinamica_generale.name': "Dinamica Generale'",
  'dinamica_generale.description':
    "Die Schnittstelle zu Produkten von Dinamica Generale ermöglichen die Integration von präzisen Fütterungsdaten. Neben den tatsächlich gefütterten Mengen an Futtermitteln geben die NIRS Sensoren einen Aufschluss über die genaue Zusammensetzung der Futtermittel.<br><br><strong>Funktionsweise:</strong><br><ol><li>Die fodjan-Schnittstelle überträgt Ihre Rationen direkt auf Futtermischwägen, welche mit Waagen von Dinamica Generale ausgestattet sind.</li><li>Die übertragene Ration/das Rezept begleitet den Misch- und Fütterungsprozess.</li><li>Im Anschluss werden die gefütterten Rationen zu fodjan übertragen.</li></ol><br><strong>Berechnung:</strong><br>Keine Berechnungen notwendig<br><br>'",
  'dinamica_generale.input_description':
    "Um sich mit Dinamica Generale zu verbinden müssen Sie zunächst die Verbindung zwischen fodjan und Dinamica Generale herstellen. Dazu loggen Sie sich in das DTM-Portal ein und gehen zum Bereich der Schnittstellen. Die hier angezeigte FARM UID fügen sie bei fodjan ein und aktivieren damit die Schnittstelle.'",
  'lab_rosenau.name': 'Futtermittellabor Rosenau',
  'lab_rosenau.description':
    'Dieses Plugin stellt die Verbindung zum Futtermittellabor Rosenau her.',
  'lab_rosenau.input_description':
    'Mit den folgenden drei Schritten aktivieren Sie Ihre Laborschnittstelle:<br><br><strong>Funktionsweise:</strong><br><ol><li> Bitte tragen Sie in das Feld „Betriebsnummer“ Ihre Betriebsnummer/Kundennummer ihre Hofes ein. Diese finden Sie zum Beispiel auf Ihren früheren Analysen oder Rechnungen. </li><li> Bitte aktivieren Sie mit dem Klick auf den „Aktivieren“-Button unten dieses Plugin, um Ihre Futteranalysen von diesem Labor direkt zu fodjan übertragen zu bekommen. </li><li> Nutzen Sie den Probenbegleitschein aus fodjan, dann bekommen wir automatisch eine Kopie aller Ihrer Analysen direkt vom Labor, um Sie Ihnen in fodjan unter „Futteranalysen“ zur Verfügung zu stellen. </li></ol>',
