    'Der Time4Cows-Connector aktiviert die Synchronisation der Daten zwischen Ihrem Lely Melkroboter und Ihrem fodjan-Betrieb.<br><br><strong>Funktionsumfang</strong><br><ul><li>Importieren von Futtergruppen aus Time4Cows in fodjan</li><li>Verknüpfung Neuer Futtermittel aus Time4Cows in fodjan</li><li>Übertragung von Futtermitteländerungen in Time4Cows an fodjan</li><li>Anlegen neuer Futtermittel aus fodjan in Time4Cows</li><li>Import der aktuellen Ration aus Time4Cows, falls diese in fodjan noch nicht bekannt ist</li></ul>',
