  'Nach dem Erstellen eines neuen Betriebs werden Sie automatisch als Nutzer mit Admin-Rechten hinzugefügt. Das heißt Sie erhalten vollen Zugriff.':
    'After setting up a new farm you will be automatically assigned as a user with admin rights. This gives you full access.',
  'Zudem werden Sie nach dem erfolgreichen Speichern zur Verwaltung des neuen Betriebs weitergeleitet.':
    'After you have successfully set up the farm you will be directed to the page for managing the new farm.',
  'Nun wird die Plugin Verwaltung geöffnet. Dort können Sie z.B. bestimmen welche Futterdatenbank geladen wird oder welche Schnittstellen aktiviert werden sollen.':
    'Now plugin administration opens. There you can specify which feed database to load or which interface to activate.',
  'Im letzten Schritt können Sie bestimmen welche Nutzer Zugriff auf den Betrieb erhalten.':
    'As a last step, you can specify which users can access to the farm.',
  'Fügen Sie an dieser Stelle Nutzer hinzu, welche Zugriff auf den Betrieb haben sollen. Je nach Lizenz können Sie dem Nutzer verschiedene Zugriffsrechte zuweisen.':
    'At this point add users who should have access to the farm. Depending on the license, you can assign different access rights to the user.',
  'Nachdem Sie den Speichern-Button gedrückt haben, überprüfen wir anhand der E-Mail-Adresse, ob der eingegebene Nutzer bereits bei fodjan angemeldet ist. In diesem Fall erhält er nun zusätzlich Zugriff auf diesen Betrieb.':
    'When you press the save button, we use the email address to check whether the user entered is already registered with fodjan. In this case the user will now be given access to this farm.',
  'Existiert die E-Mail noch nicht in unserem System, wird ein neuer Nutzer erstellt und per E-Mail benachrichtigt (falls angekreuzt).':
    'If the email address is not yet registered on our system, a new user will be created and informed by email (if the appropriate box has been checked).',
