  'Ich ermächtige die fodjan GmbH, Großenhainer Straße 101, 01127 Dresden (Gläubiger-Identifikationsnummer: DE59 ZZZ 00001530052) bzw. den von der fodjan GmbH beauftragten Zahlungsabwickler Stripe Payments Europe, Ltd. (Gläubiger-Identifikationsnummer: DE16 ZZZ 00001941136) Zahlungen von meinem Konto mittels SEPA-Lastschrift einzuziehen. Zugleich weise ich mein Kreditinstitut an, die von der fodjan GmbH auf mein Konto gezogenen Lastschriften einzulösen. Anmerkungen:':
    'I authorize fodjan GmbH, Großenhainer Straße 101, 01127 Dresden (Creditor identification number: DE59 ZZZ 00001530052) respectively the payment processor assigned by fodjan GmbH, Stripe Payments Europe, Ltd. (Creditor identification number: DE16 ZZZ 00001941136), to collect payments from my account by direct debit. At the same time, I instruct my bank to redeem the direct debits drawn by fodjan GmbH on my account. Notes:',
  'Ich kann innerhalb von acht Wochen, beginnend mit dem Belastungsdatum, die Erstattung des belasteten Betrages verlangen. Es gelten dabei die mit meinem Kreditinstitut vereinbarten Bedingungen. Die Mandatsreferenz wird Ihnen separat auf der Rechnung mitgeteilt.':
    'I can claim reimbursement of the debited amount from my bank within eight weeks of the debit date. The terms agreed with my bank apply in this regard. The mandate reference will be communicated to you separately on the invoice.',
  'Stripe ist ein Dienstleister, der den Abgleich Ihrer Zahlungsdaten mit den jeweiligen Kreditinstituten (Visa, Mastercard etc.) oder Ihrem Bankinstitut vornimmt. Die geltenden Datenschutzbestimmungen von Stripe können unter https://stripe.com/de/privacy abgerufen werden.':
    'Stripe is a service provider that performs the balancing of your payment data with the respective credit institutions (Visa, Mastercard etc.) or your bank. The current data protection regulations of Stripe can be retrieved from https://stripe.com/de/privacy.',
