  'Willkommen im Assistenten zum schnellen Einrichten Ihres Betriebes.':
    'Welcome to the assistant to quickly set up your farm.',
  'Ziel ist es in wenigen Schritten eine verbesserte Ration zu finden. Um diese auch praktikabel einsetzbar zu machen, nehmen wir Ihre zur Zeit gefütterte Ration als Basis dieser Berechnung.':
    'The goal is to find an improved ration in just a few steps. In order to make this practicable, we use the ration your currently feed as the basis for this calculation.',
