  'Wiederholte Registrierung': 'Repeated registration',
  'nicht erstellt': 'not created',
  'E-Mail erfolgreich verifiziert': 'E-mail successfully verified',
  'die E-Mail-Adresse mit der Sie sich soeben bei fodjan.de registrieren wollten, ist bereits für fodjan Pro oder unsere App hinterlegt. Daher ist es uns leider nicht möglich eine neue Registrierung für Sie vorzunehmen. Um ihr Konto zu verwenden, können Sie gern die Passwort-vergessen–Funktion verwenden und sich ein neues Passwort hinterlegen, mit dem Sie sich in fodjan Pro und unserer App anmelden können.':
    'the email address you just want to register with fodjan.de, is already stored for fodjan Pro or our App. Therefore, it is unfortunately not possible to make a new registration for you. To use your account, you are welcome to use the password forgot feature and set a new password to log in to fodjan Pro and our App.',
  'E-Mail nicht verifiziert': 'E-mail not verified',
  'die E-Mail-Adresse mit der Sie sich soeben bei fodjan.de registrieren wollten, ist bereits bei uns hinterlegt, aber noch nicht bestätigt. Daher ist es uns leider nicht möglich eine neue Registrierung für Sie vorzunehmen. Um ihr Konto zu aktivieren, können Sie gern die Passwort-vergessen–Funktion verwenden und sich ein neues Passwort hinterlegen.':
    'the email address you just want to register with fodjan.de, is already deposited with us, but not confirmed. Therefore, it is unfortunately not possible to make a new registration for you. To activate your account, you are welcome to use the password forgot feature and to set a new password.',
