  'Ihr persönlicher Fütterungsassistent': 'Uw persoonlijke voederingsassistent',
  'fodjan ist eine webbasierte Plattform zum Fütterungsmanagement, dazu zählen die Rationsgestaltung, das Futtermanagement und die Vernetzung von Daten, Technik und Beratern in landwirtschaftlichen Betrieben. Der Zugang erfolgt via Internet über die Software fodjan pro oder die fodjan App. fodjan versteht sich als Werkzeug um die Fütterung der Nutztiere gesünder zu gestalten und gleichzeitig Futterkosten und Futtereffizienz im Griff zu haben und zu verbessern. Auf der Plattform werden fütterungsrelevante Daten vereint und für den Anwender nutzbar und auswertbar bereitgestellt.':
    'fodjan is een web-gebaseerd platform voor voederingsmanagement dat de samenstelling van rantsoenen, het voedermanagement omvat. Op het platform worden gegevens, techniek en adviseurs in landbouwbedrijven aan elkaar gekoppeld. De toegang loopt via internet met de software fodjan pro of de fodjan-app. fodjan is bedoeld als instrument om de voedering van vee gezonder te maken en tegelijkertijd de voerkosten en -efficiëntie onder controle te houden en te verbeteren. Op het platform worden relevante gegevens voor de voedering met elkaar gecombineerd en in bruikbare en analyseerbare vorm aan de gebruiker gepresenteerd.',
  Kooperationen: 'Samenwerkingen',
  'Lely und fodjan mit neuer Partnerschaft.':
    'Lely en fodjan met nieuw partnerschap.',
  'Lely und fodjan kooperieren in der Entwicklung':
    'Lely en fodjan werken samen bij de ontwikkeling',
  'Für Milchviehbetriebe ist die Fütterung ein wichtiger Erfolgs- und Kostenfaktor. Daher wollen wir zusammen mit der %s%Lely Gruppe%t% aus den Niederlanden unsere innovative Fütterungssoftware weiter entwickeln und die Vernetzung des Milchviehstalls vorantreiben.':
    'Voor melkveebedrijven is de voedering een belangrijke factor voor succes en kosten. Daarom willen we samen met de Nederlandse %s%Lely-groep%t% onze innovatieve voederingssoftware verder ontwikkelen en opname van de melkveestal in netwerken stimuleren.',
  'Zur Pressemitteilung': 'Naar persbericht',
  'Fütterrungsprofis der BayWa nutzen fodjan':
    'Professionals in het voederen van BayWa gebruiken fodjan',
  'Durch die Kooperation mit dem Agrarkonzern %s%BayWa%t% wird ein neues Produkt geschaffen, das die Rationszusammenstellung für BayWa-Kunden tiergerechter und effizienter gestaltet. Die Zusammenarbeit zwischen Landwirten und Fütterungsberater wird dadurch auf ein neues Niveau gehoben.':
    'Door de samenwerking met het agrarische concern %s%BayWa%t% wordt een nieuw product gecreëerd, dat rantsoenen voor BayWa-klanten efficiënt, maar met aandacht voor de dieren samenstelt. De samenwerking tussen veetelers en voedingsadviseurs wordt daardoor naar een nieuw niveau getild.',
  'Zur BayWa-Kooperationsseite': 'Naar de BayWa-samenwerkingspagina',
