  'Mit der fodjan-Fütterungssoftware mache ich das Feintuning für die Futterrationen unserer 1000-köpfigen Milchviehherde. (...) Mithilfe des Programms kriege ich schnell mit, was gut ist und was nicht.':
    'Met de fodjan-voederingssoftware zorg ik voor de fijne afstemming van voederrantsoenen voor onze melkveestapel van 1000 dieren. (...) Met dit programma kom ik snel te weten wat goed is en wat niet.',
