  NDIP: 'NDIP',
  'NutriOpt verdauliches Darmprotein - Dies ist die Summe aus mikrobieller Proteinausbeute im Pansen und Bypass-Protein, das im Dünndarm verdaut wird. ':
    "NutriOpt Digestible Intestinal Protein - Questo è il totale delle proteine microbiche prodotte nel rumine e delle proteine di bypass digerite nell'intestino tenue.",
  NFEPB: 'NFEPB',
  'NutriOpt vergärbare Energie- und Proteinbilanz - Dies ist die Bilanz von vergärbaren Kohlenhydraten und Proteinen im Pansen. Im Wesentlichen ist NFEPB die Menge an TFP, die über das für die mikrobielle Proteinsynthese erforderliche fermentierbare Protein hinausgeht. ':
    "NutriOpt Fermentable Energy and Protein Balance - Questo è l'equilibrio di carboidrati e proteine fermentabili nel rumine. Essenzialmente, NFEPB è la quantità di TFP in eccesso rispetto alle proteine fermentabili necessarie per la sintesi proteica microbica.",
  RFP: 'RFP',
  'Schnell vergärbares Protein - Die Menge des im Pansen vergorenen Proteins in weniger als zwei Stunden nach der Fütterung. Wird im Pansen benötigt, um das Wachstum von mikrobiellen Proteinen voranzutreiben. Niedrige Werte können zu geringer Leistung und reduzierter TMA führen. Überschüssige Mengen können zu weichem Kot und reduzierter Pansenenergie führen.':
    "Proteine rapidamente fermentabili - La quantità di proteine fermentate nel rumine in meno di due ore dopo l'alimentazione. Necessaria nel rumine per guidare la crescita microbica delle proteine. Bassi livelli possono portare a basse prestazioni e a un DMI ridotto. Quantità eccessive possono portare a feci molli e a una riduzione dell'energia nel rumine.",
  TFP: 'TFP',
  'Summe vergärbares Protein - TFP ist die Summe von RFP und SFP. TFP ist wichtig, um genügend vergärbares Protein für eine effiziente mikrobielle Proteinsynthese zu liefern.':
    "Proteine fermentabili totali - TFP è il totale di RFP e SFP. La TFP è importante per fornire abbastanza proteine fermentabili per un'efficiente sintesi proteica microbica.",
