  'im Dünndarm verdauliches Eiweiß': "proteine digeribili nell'intestino tenue",
  'Proteinabsorption - Energielimitierend; echtes Protein kann im Dünndarm absorbiert werden, wenn die im Pansen fermentierbare Energie (organische Substanz) die mikrobielle Proteinsynthese im Pansen begrenzt':
    "Assorbimento delle proteine - Limitazione dell'energia; vera proteina assorbibile nell'intestino tenue quando l'energia fermentabile nel rumine (materia organica) limita la sintesi proteica microbica nel rumine",
