  'Die Testphase ist für Sie selbstverständlich kostenlos und unverbindlich. Ihnen entstehen keine Folgekosten.':
    'Il periodo di prova è ovviamente gratuito e non vincolante. Non dovrai sostenere alcun costo.',
  'Sparen Sie Futterkosten und verbessern Sie gleichzeitig die Gesundheit Ihrer Tiere.':
    'Risparmia sui costi del alimenti e migliora la salute dei tuoi animali allo stesso tempo.',
