  'fodjan smart feeding - Rationsberechnung der neuen Generation. Hier finden Sie alle Informationen zum Datenschutz.':
    'fodjan smart feeding - Calcolo delle razioni di nuova generazione. Qui trovi tutte le informazioni sulla protezione dei dati.',
  'Falls Sie das Exklusivpaket "BayWa Rind" für BayWa-Kunden bestellen wollen, registrieren Sie sich bitte auf der':
    'Se vuoi ordinare l’esclusivo pacchetto "BayWa Rind" per i clienti BayWa, registrati sul',
  'Website der BayWa.': 'Sito di BayWa.',
  'Das Thema Fütterung ist ein wesentlicher Erfolgsfaktor im Milchviehbetrieb. Hierbei kommt es auf den richtigen Einsatz von Futtermitteln, die Futterbedarfsplanung, das Herdenmanagement als auch auf die Rationsberechnung an.':
    'L’alimentazione è un fattore essenziale per il successo negli allevamenti di bestiame da latte. L’uso corretto del alimenti, la pianificazione del fabbisogno alimentare, la gestione della azienda e il calcolo delle razioni sono tutti elementi importanti.',
  'Immer mit dem Ziel vor Augen, die richtige Balance zwischen Tiergesundheit und Kosten zu halten.':
    'Sempre con l’obiettivo di mantenere il giusto equilibrio tra salute degli animali e costi.',
  'Hierbei unterstützt Sie fodjan smart feeding. Egal ob mit oder ohne Berater an Ihrer Seite.':
    'Qui entra in gioco smart feeding. Con o senza un nutrizionista al tuo fianco.',
  'Mit der Fütterungssoftware schaffen Sie es schnell und einfach, gesunde und kostengünstige Rationen zu finden.':
    'Con questo software di alimentazione puoi trovare rapidamente e facilmente razioni sane e convenienti.',
  'Betriebe mit Berater': 'Aziende con nutrizionista',
  'Betriebe, die mit Beratern zusammenarbeiten, profitieren vom umfassenden Knowhow und dem hohen Erfahrungsschatz der Experten.':
    'Le aziende che lavorano con consulenti beneficiano del know-how completo e della competenza degli esperti.',
  'Hier ist fodjan ein hilfreiches Werkzeug, um Beratern mit der innovativen Fütterungssoftware unterstützend zur Seite zu stehen und mehr Transparenz zwischen Landwirt und Berater zu schaffen.':
    'In questo caso fodjan si rivela uno strumento utile per sostenere i consulenti grazie all’innovativo software di alimentazione e alla maggiore trasparenza tra l’allevatore e il nutrizionista.',
  'Für die gemeinsame Nutzung erhalten beide einen Zugang zur Software.':
    'Per l’uso congiunto, entrambi ricevono l’accesso al software.',
  'Betriebe ohne Berater': 'Aziende senza nutrizionista',
  'Auch für Betriebe, die ohne Berater arbeiten und die Fütterung der Milchkühe selbst in die Hand nehmen, ist fodjan ein ideales Programm, um die Futterbestände übersichtlich zu verwalten und die geeignetste Ration zu finden.':
    'fodjan è un programma ideale anche per le aziende che lavorano senza consulenti e gestiscono da sole l’alimentazione delle vacche da latte, per gestire in modo chiaro i carichi di alimenti e trovare la razione più adatta.',
  'Viele Betriebe, auch ohne Berater, finden mit fodjan gesündere Rationen - ohne dabei mehr investieren zu müssen. Im Gegenteil: Die Betriebe sparen durchschnittlich 10 % ihrer Futterkosten ein.':
    'Molte aziende, anche senza consulenti, trovano razioni più sane con fodjan - senza dover investire di più. Al contrario: Le aziende risparmiano in media il 10 % dei costi per il alimenti.',
  'Milchvieh- und Futterberater':
    'Nutrizionista per mangimi e bestiame da latte',
  'Sie sind Milchvieh- bzw. Futterberater und möchten Ihre Betriebe individuell und bestmöglich beraten? Mit dem innovativen Fütterungsprogramm fodjan smart feeding können Sie mehrere Betriebe gleichzeitig beraten und optimieren.':
    'Sei un nutrizionista di bestiame da latte o di mangimi e vorresti offrire alle tue aziende la miglior consulenza individuale possibile? Grazie all’innovativo programma di alimentazione fodjan smart feeding puoi consigliare e ottimizzare più aziende allo stesso tempo.',
  'Ob Planung, Rationsberechnung oder Futtergesundheitsbewertung – fodjan findet für jeden Betrieb gesündere und kostengünstigere Rationen.':
    'Che si tratti di pianificazione, calcolo della razione o valutazione della salubrità del alimenti, fodjan elabora razioni più sane e convenienti per ogni azienda.',
