  'Die neue Generation der Rationsberechnung':
    'La nuova generazione del calcolo delle razioni',
  'Die fodjan GmbH wurde im September 2014 in Dresden gegründet. Carsten Gieseler, Geschäftsführer der fodjan GmbH, entwickelte die Idee für die smart feeding Software während seines Agrar – und Betriebswirtschaftsstudiums. In Zusammenarbeit mit dem Informatiker Johannes Völker, dem Betriebswirt Michael Schütze, dem Webentwickler Daniel Schreck und dem Algorithmus-Spezialist Paul Völker entwickelte das Team die Software bis zur Marktreife und testete die Pilotversion erfolgreich in mehreren großen landwirtschaftlichen Betrieben.':
    'fodjan GmbH è stata fondata a Dresda nel settembre 2014. Carsten Gieseler, amministratore delegato di fodjan GmbH, ha sviluppato l’idea del software di alimentazione intelligente durante i suoi studi in agronomia e economia aziendale. In collaborazione con l’informatico Johannes Völker, l’economista aziendale Michael Schütze, lo sviluppatore web Daniel Schreck e lo specialista di algoritmi Paul Völker, il team ha sviluppato il software fino a renderlo pronto per il mercato, e ha testato con successo la versione pilota su varie grandi aziende.',
  'Impressum. Kontaktdaten und weitere nützliche Infos zu fodjan, der Softwarelösung der modernen Rationsberechnung.':
    'Annotazione di pubblicazione. Dati di contatto e altre informazioni utili su fodjan, la soluzione software per il calcolo moderno delle razioni.',
