  'Buchen Sie noch <strong>bis zum 15. Januar</strong> fodjan Pro oder den Standard Beraterzugang für ein Jahr und sparen Sie 100€. Testen Sie fodjan wie gewohnt 14 Tage kostenlos und geben Sie anschließend folgenden Gutscheincode beim Buchen der Lizenz ein:':
    'Prenota <strong>fino al 15 gennaio</strong> fodjan Pro o l’accesso nutrizionista standard per un anno, e risparmia 100€. Prova fodjan come al solito per 14 giorni gratuitamente, dopodiché inserisci il seguente voucher al momento della prenotazione della licenza:',
  'Das Buchungsformular finden Sie wie folgt: Login -> Verwaltung -> Lizenz buchen':
    'Puoi trovare il modulo di prenotazione qui: Accesso -> Amministrazione -> Prenota licenza',
  'fodjan smart feeding Milchkuh ist eine interaktive und internetbasierte Software zur Futterrationsberechnung für Milchkühe. Das innovative Programm ermöglicht erstmals eine Verbesserung der Tiergesundheit bei gleichzeitiger Reduktion der Futterkosten. Durch einen speziell entwickelten Algorithmus erspart fodjan smart feeding dem Nutzer das zeitaufwändige Ausprobieren verschiedener Futterrationen. Die Bedienung ist einfach und intuitiv gestaltet – die Rechenarbeit erledigt der Algorithmus.':
    'fodjan smart feeding per vacche da latte è un software interattivo e basato su internet per il calcolo della razione di foraggio per vacche da latte. Questo innovativo programma permette per la prima volta di migliorare la salute degli animali riducendo allo stesso tempo i costi alimentari. Grazie a un algoritmo appositamente sviluppato, fodjan smart feeding risparmia all’utente di dover provare diverse razioni, con la perdita di tempo che ne consegue. Il funzionamento è stato studiato per essere semplice e intuitivo - l’algoritmo svolge il lavoro di calcolo.',
  '<h4 class="data-title-header">DCAB (Kationen-Anionen-Bilanz)</h4>Der DCAB-Wert ist nur dann zuverlässig, wenn alle Futtermittel auf Na, K, Cl und S geprüft sind. ':
    '<h4 class="data-title-header">DCAB (equilibrio cationi-anioni)</h4>Il valore DCAB è affidabile solo se in tutti i mangimi sono stati determinati i tenori di Na, K, Cl e S. ',
