  'Ich bin mir sicher, dass das Futtermittel in den genannten Rationen ersetzt werden soll. Das originale Mischfutter wird archiviert.':
    'Ich bin mir sicher, dass das Futtermittel in den genannten Rationen ersetzt werden soll. Das originale Mischfutter wird archiviert.',
  'Ich bin mir sicher, dass das Futtermittel in den genannten Rationen ersetzt werden soll. Das originale Mischfutter bleibt im Bestand.':
    'Ich bin mir sicher, dass das Futtermittel in den genannten Rationen ersetzt werden soll. Das originale Mischfutter bleibt im Bestand.',
  'Das Mischfutter wird in den Bestand aufgenommen und in dieser Ration angezeigt, nachdem Sie unten auf "Mischfuttern speichern" geklickt haben. <br/><br/>Es wird der Ration jedoch erst mit dem Speichern der Ration hinzugefügt. Bis dahin können Sie die Rationsbearbeitung noch abbrechen, wodurch das bisherige Mischfutter in der Ration wiederhergestellt wird. <br/><br/>Das originale Mischfutter wird daher <u>nicht archiviert</u>.':
    'Das Mischfutter wird in den Bestand aufgenommen und in dieser Ration angezeigt, nachdem Sie unten auf "Mischfuttern speichern" geklickt haben. <br/><br/>Es wird der Ration jedoch erst mit dem Speichern der Ration hinzugefügt. Bis dahin können Sie die Rationsbearbeitung noch abbrechen, wodurch das bisherige Mischfutter in der Ration wiederhergestellt wird. <br/><br/>Das originale Mischfutter wird daher <u>nicht archiviert</u>.',
  'Das originale Mischfutter wird <u>archiviert</u>. Ab Speicherung überschreibt dieses Mischfutter das vorherige Mischfutter in allen Rationen, außer in Rationen, die in der Vergangenheit gefüttert wurden, jetzt aber nicht mehr aktiv sind. In diesen wird weiterhin das archivierte Mischfutter angezeigt.':
    'Das originale Mischfutter wird <u>archiviert</u>. Ab Speicherung überschreibt dieses Mischfutter das vorherige Mischfutter in allen Rationen, außer in Rationen, die in der Vergangenheit gefüttert wurden, jetzt aber nicht mehr aktiv sind. In diesen wird weiterhin das archivierte Mischfutter angezeigt.',
  'Ab dem gesetzten Datum überschreibt dieses Mischfutter den vorherigen Stand des Mischfutters in allen Rationen, außer in Rationen, die in der Vergangenheit gefüttert wurden, jetzt aber nicht mehr aktiv sind. In diesen wird weiterhin das archivierte Mischfutter angezeigt. Das originale Mischfutter wird <u>nicht archiviert</u>.':
    'Ab dem gesetzten Datum überschreibt dieses Mischfutter den vorherigen Stand des Mischfutters in allen Rationen, außer in Rationen, die in der Vergangenheit gefüttert wurden, jetzt aber nicht mehr aktiv sind. In diesen wird weiterhin das archivierte Mischfutter angezeigt. Das originale Mischfutter wird <u>nicht archiviert</u>.',
