  'Milch Gesamt': 'Milch Gesamt',
  'mlp.urea.warning':
    'Der Harnstoffgehalt ist ein Indikator für die Eiweißversorgung der Milchkuh. Der optimale Harnstoffgehalt (180 mg/l bis 230 mg/l) wird heute aus Sicht eines geringeren Stickstoffeintrages in die Umwelt angegeben. Dieser Wert kann durch den Einsatz von ungeschütztem Futterharnstoff nach oben gehen bzw. durch den Einsatz von geschützten Eiweiß reduziert werden.',
  'mlp.energy_deficiency.warning':
    'Um eine Energiemangelsituation in der Herde aufzudecken, wird der Fett-Eiweiß-Quotient (FEQ > 1,5) sowie die Beurteilung der Eiweißversorgung (abh. von der Milchleistung) verwendet. Wird einer dieser Parameter erfüllt, befindet sich die Kuh in einer energetischen Unterversorgung.  Folgen können Fruchtbarkeitsstörungen, verminderte Milchleistung, subklinische Ketose oder vor allem in den ersten 30 Laktationstagen ein Abbau der Körperreserven sein.',
  'mlp.rumen_health_risk.warning':
    'Gerade zu Laktationsbeginn und bei einer physiologisch niedrigeren Futteraufnahme besteht die Gefahr einer Pansenübersäuerung (niedriger Milchfettgehalt). Einzelne Kühe sind trotz niedrigem Fettgehalt (Magermilch) sehr leistungsbereit und gesund. Diese Kühe steuern ihre Energieausscheidung sehr intelligent, indem sie weniger Fett produzieren. Andere Kühe neigen zu einer Übersäuerung, vor allem wenn die Grundfutteraufnahme im Vergleich zum Kraftfutter zu gering ist. Das Ziel sollte immer sein, dass die Kuh mindestens 60 % Grundfutter aufnimmt.',
  'mlp.ketosis_risk.warning':
    'Ein Ketoseverdacht in der Herde besteht, wenn der Fett-Eiweiß-Quotient zu hoch (FEQ > 1,5) und dabei zeitgleich der Eiweißgehalt in Abhängigkeit der Milchleistung zu niedrig ist. Diese energetische Unterversorgung führt über einen längeren Zeitraum, vor allem in den ersten Laktationswochen, zu einer Ketose. Weitere Folgen können Abmagerung, starker Rückgang der Futteraufnahme, Leberverfettung und ein vermehrtes Auftreten von Ketonkörper in Harn und Blut sein.',
  'mlp.obesity_risk.warning':
    'Der Milcheiweißgehalt am Ende der Laktation ist eine der besten Kennzahlen um eine Verfettung der Kühe festzustellen. Aufgrund der hohen Erblichkeit dieses Parameters muss unbedingt berücksichtigt werden, dass „eiweißstarke“ Kühe am Ende der Laktation einen deutlich höheren Milcheiweißgehalt haben als „eiweißschwache“ Kühe. D.h ab einem Anstieg des Eiweißgehaltes von mehr als 0, 6 %-Punkte im Vergleich zum Durchschnitt der vorangegangenen 200 Laktationstagen der Kuh besteht die Gefahr einer Verfettung.',
