  'fodjan Service':
    'Zostałeś dodany do gospodarstwa w aplikacji fodjan. Aby pomyślnie zakończyć rejestrację, musisz jeszcze potwierdzić otrzymanie tej wiadomości. Wystarczy kliknąć na poniższy link',
  'Sie erhalten diese automatische E-Mail, weil Sie Ihr Passwort bei fodjan erfolgreich geändert haben.<br><br>Falls Sie nicht selbst diese Änderung vorgenommen haben, wurde Ihr Konto möglicherweise gehackt.<br><br>In diesem Fall sollten Sie Ihr Passwort zurückzusetzen. Klicken Sie dafür auf folgenden Link':
    'U ontvangt deze email omdat u uw wachtwoord hebt gewijzigd.',
  'fodjan smart feeding ist eine neue Generation landwirtschaftlicher Fütterungssoftware für Landwirte, Fütterungsberater und Tierärzte. Das innovative Programm vereinfacht die Rationsberechnung und vernetzt Sie im gesamten Fütterungsprozess':
    'fodjan smart Paszaing to oprogramowanie nowej generacji dla rolników, doradców żywieniowych i weterynarzy. Innowacyjny program ułatwia obliczanie dawek pokarmowych i pozwala uczestniczyć w całym procesie żywienia.',
  'Das Rationsberechnungsprogramm fodjan smart feeding wurde speziell für Milchviehhalter entwickelt und bewertet die Futtergesundheit Ihrer Ration, um Folgen falscher Fütterung, die zu Milchfieber, Pansenazidose und Klauenerkrankungen führen können, vorzubeugen. Gleichzeitig haben Sie Überblick über aktuelle wirtschaftliche Kennzahlen Ihres Betriebs und die Möglichkeit zur Optimierung Ihrer Ration hinsichtlich Futterkosten, -effizienz, Milchmenge, IOFC uvm . Wir geben Ihnen die Möglichkeit auf aktuelle Regulatorien – wie z.B. Düngeverordnung und GVO-freie Fütterung - zu reagieren. Probieren Sie fodjan als Landwirt, Fütterungsberater oder Tierarzt mit der Pro-Version für Ihren Desktop.':
    'Het rantsoenberekeningsprogramma fodjan smart feeding is gemaakt voor melkveehouders en evalueert de gezondheid van uw voermengsel, ter voorkoming van bijvoorbeeld pensverzuring, melkziekte en baringparese. Tegelijkertijd krijgt u een overzicht van de economische cijfers van uw bedrijf en de kans om uw rantsoen te optimaliseren met betrekking tot voerkosten, hoeveelheid melk, IOFC etc. Wij geven u de kracht om te reageren op actuele regelgeving, bijvoorbeeld om GMO-vrij te voeren. Test fodjan nu als boer, voederadviseur of dierenarts met de pro-versie voor uw computer.',
