  'Vorlage aus Datenbank oder Bestand benutzen':
    'Use template from database or stock',
  'Wenn sie ein Futtermittel aus dem Bestand auswählen, wird dieses als Vorlage verwendet und aktualisiert. Dabei werden alle aktuellen und zukünftig geplanten Rationen mit aktualisiert. Wenn sie ein Datenbank-Futtermittel auswählen, wird dieses als Vorlage für ein neues Bestandsfuttermittel verwendet.':
    'If you select a feed from the stock, it will be used as a template and updated. All current and future planned rations are also updated. If you select a database feed, it will be used as a template for a new stock feed.',
