  'Ration konnte nicht gespeichert werden. Sie werden in die Rationsübersicht weitergeleitet.':
    'The ration could not be saved. You will be redirected to the ration overview.',
  'Korrektur Faktor': 'Correction factor',
  'Das Rationsberechnungsprogramm smart feeding gibt es nun auch speziell für die Rindermast mit 3- oder 7-phasiger Fütterung. Sie können die Futtergesundheitsbewertungen Ihrer Rationen einsehen und somit gesundheitlichen Folgen wie Pansenazidose und Klauenerkrankungen vorbeugen. Gleichzeitig haben Sie Überblick über aktuelle wirtschaftliche Kennzahlen Ihres Betriebs und die Möglichkeit zur Optimierung Ihrer Ration hinsichtlich Futterkosten, -effizienz, uvm. Wir geben Ihnen die Möglichkeit auf aktuelle Regulatorien – wie z.B. Düngeverordnung und GVO-freie Fütterung - zu reagieren. Probieren Sie fodjan als Landwirt, Fütterungsberater oder Tierarzt mit der Pro-Version für Ihren Desktop.':
    'Program obliczania dawki pokarmowej smart feeding jest teraz dostępny również specjalnie dla bydła opasowego z 3- lub 7-fazowym żywieniem. Możesz przeglądać oceny zdrowotności paszy w swoich dawkach i w ten sposób zapobiegać konsekwencjom zdrowotnym, takim jak kwasica żwacza czy choroby racic. Jednocześnie mają Państwo wgląd w aktualne kluczowe dane ekonomiczne gospodarstwa i możliwość optymalizacji dawki pokarmowej pod względem kosztów paszy, efektywności żywienia itp.Dajemy możliwość reagowania na aktualne przepisy - takie jak przepisy dotyczące nawozów czy żywienia bez GMO. Wypróbuj fodjan jako rolnik, doradca żywieniowy lub weterynarz z wersją Pro na pulpit.',
