  'Sending email...': 'Sending email...',
  'Auf unserer Seite haben Sie die Möglichkeit sich für unsere themenbezogenen Newsletter und Mailings anzumelden. Für eine Anmeldung reicht es grundsätzlich aus, wenn Sie Ihre E-Mail-Adresse angeben. Um eine persönliche Ansprache zu ermöglichen, bitten wir Sie optional Vor- und/oder Nachnamen anzugeben. Welche personenbezogenen Daten weiterhin an uns übermittelt werden, ergibt sich aus der hierzu verwendeten Eingabemaske. Sofern im Rahmen einer Anmeldung dessen Inhalte konkret umschrieben werden, sind sie für die Einwilligung der Nutzer maßgeblich. Indem Sie unseren Newsletter abonnieren, erklären Sie sich mit dem Empfang und den beschriebenen Verfahren einverstanden.':
    'Na naszej stronie internetowej mają Państwo możliwość zarejestrowania się na nasze tematyczne newslettery i mailingi. Aby się zarejestrować wystarczy podać swój adres e-mail. W celu włączenia osobistego adresu prosimy o opcjonalne podanie imienia i/lub nazwiska.Dane osobowe, które również zostaną nam przekazane, można zobaczyć w masce wprowadzania danych, która służy do tego celu. Jeśli treści te są konkretnie opisane w kontekście rejestracji, decydują one o zgodzie użytkownika. Zapisując się na nasz newsletter, wyrażasz zgodę na jego otrzymywanie oraz na opisane procedury.',
